          <div class="keyword-section-title"><span>热门令字</span><small>POPULAR CHARACTERS · {{ popularKeywords.length }}</small></div><div class="keyword-grid"><button v-for="item in popularKeywords" :key="item.char" class="keyword-token" :class="{ chosen: selectedKeyword === item.char }" @click="selectKeyword(item.char)"><span>{{ item.char }}</span><small>{{ item.count }} 句</small></button></div>
          <div class="keyword-section-title more-title"><span>更多令字</span><small>MORE CHARACTERS</small></div><div class="more-keywords"><button v-for="char in moreKeywords" :key="char" :class="{ chosen: selectedKeyword === char }" @click="selectKeyword(char)">{{ char }}</button></div>
          <div class="custom-keyword"><span>自定义令字</span><input v-model.trim="customKeyword" maxlength="1" placeholder="一字" @keyup.enter="useCustomKeyword"><button class="small-button" :disabled="!customKeyword" @click="useCustomKeyword">落定</button></div>
